def _fill_artifacts(self, report: Any) -> None:
    self._last_obfuscation = report if isinstance(report, ObfuscationReport) else None
    if self._artifact_list is None:
        return
    self._artifact_list.clear()
    if self._last_obfuscation is None:
        return
    for index, artifact in enumerate(self._last_obfuscation.decoded_artifacts):
        item = QtWidgets.QListWidgetItem(format_artifact_row(artifact))
        item.setData(QtCore.Qt.UserRole, index)
        self._artifact_list.addItem(item)

def _propose_deobfuscation(self) -> None:
    if self._actions.propose_deobfuscation is None:
        return
    try:
        status = self._actions.propose_deobfuscation()
    except Exception as exc:  # a button click must never raise into IDA's event loop
        status = "Deobfuscation failed: {0}".format(_short_error(exc))
    self._set_status(status)
    self.refresh_changes()

def _propose_decoded_comments(self) -> None:
    report = self._last_obfuscation
    if report is None:
        self._set_status("Run Obfuscation first")
        return
    if self._actions.propose_decoded_comments is None:
        self._set_status("Comment proposals are unavailable")
        return
    try:
        queued = int(self._actions.propose_decoded_comments(report))
    except Exception as exc:  # a button click must never raise into IDA's event loop
        self._set_status("Proposal failed: {0}".format(type(exc).__name__))
        return
    self._set_status("{0} comment proposal(s) queued for approval — see Proposed Changes".format(queued))
    self.refresh_changes()

def _selected_artifact(self) -> Any:
    if self._artifact_list is None or self._last_obfuscation is None:
        return None
    item = self._artifact_list.currentItem()
    if item is None:
        return None
    index = item.data(QtCore.Qt.UserRole)
    artifacts = self._last_obfuscation.decoded_artifacts
    if isinstance(index, int) and not isinstance(index, bool) and 0 <= index < len(artifacts):
        return artifacts[index]
    return None

def _copy_python_snippet(self) -> None:
    artifact = self._selected_artifact()
    if artifact is None:
        self._set_status("Select a decoded artifact first")
        return
    snippet = getattr(artifact, "python_snippet", None)
    if not snippet:
        self._set_status("The selected artifact has no Python snippet (only recipe artifacts do)")
        return
    application = getattr(QtWidgets, "QApplication", None)
    clipboard = None
    try:
        clipboard = application.clipboard() if application is not None else None
    except Exception:
        clipboard = None
    if clipboard is None:
        self._set_status("Clipboard unavailable")
        return
    try:
        clipboard.setText(snippet)
    except Exception as exc:
        self._set_status("Copy failed: {0}".format(type(exc).__name__))
        return
    self._set_status("Python snippet copied — " + COPY_PYTHON_NOTE)

def _show_error(self, message: str) -> None:
    self._set_status(message)
    self._update_cancel_button()
    self.refresh_changes()

def _select_tab(self, index: int) -> None:
    """Bring the result tab forward unless the analyst moved to another tab while it ran;
    then only highlight the result tab so their current view is not yanked away."""
    if self._tabs is None:
        return
    current = self._tabs.currentIndex()
    moved = self._tab_at_start is not None and current != self._tab_at_start
    if moved and current != index:
        try:
            bar = self._tabs.tabBar()
            bar.setTabTextColor(index, bar.palette().color(bar.palette().Highlight))
            if not getattr(self, "_highlight_hooked", False):
                self._tabs.currentChanged.connect(self._clear_tab_highlight)
                self._highlight_hooked = True
        except Exception:
            self._tabs.setCurrentIndex(index)
        return
    self._tabs.setCurrentIndex(index)

def _clear_tab_highlight(self, index: int) -> None:
    try:
        bar = self._tabs.tabBar()
        bar.setTabTextColor(index, bar.palette().color(bar.palette().WindowText))
    except Exception:
        pass

