class GridFlowLayout(FlowLayout):
    """Uniform button grid that reflows its column count with the dock width.

    The Qt counterpart of CSS ``grid-template-columns: repeat(auto-fill,
    minmax(<widest button>, 1fr))``: every cell is as wide as the widest
    button, as many columns fit as the width allows, and the cells stretch
    to fill the row so the buttons line up in rows and columns.
    """

    def expandingDirections(self):  # noqa: N802 - Qt override
        return QtCore.Qt.Horizontal

    def _arrange(self, rect, apply: bool) -> int:
        margins = self.contentsMargins()
        left = rect.x() + margins.left()
        top = rect.y() + margins.top()
        available = max(1, rect.width() - margins.left() - margins.right())
        visible = self._visible()
        if not visible:
            return margins.top() + margins.bottom()
        cell_width = max(item.sizeHint().width() for item in visible)
        cell_height = max(item.sizeHint().height() for item in visible)
        columns = max(1, min(len(visible), (available + self._gap) // (cell_width + self._gap)))
        width = max(1, (available - self._gap * (columns - 1)) // columns)
        for index, item in enumerate(visible):
            row, column = divmod(index, columns)
            if apply:
                item.setGeometry(QtCore.QRect(left + column * (width + self._gap),
                                              top + row * (cell_height + self._gap), width, cell_height))
        rows = (len(visible) + columns - 1) // columns
        return rows * cell_height + (rows - 1) * self._gap + margins.top() + margins.bottom()

