                sample["Embedded executables"] = "; ".join(pe.embedded_executables[:4])
        data = full_report_module.FullReportData(
            binary_name=binary_name,
            generated_at=generated_at,
            sample=sample,
            verdict=outcome.verdict,
            triage=outcome.report,
            packing=outcome.packing,
            flows=outcome.flows,
            path=outcome.path,
            origin_index=origin_index,
            functions=tuple(functions),
            investigation=investigation,
            analysed_new=new_count,
            reused=len(reused),
            planned=plan.functions_planned,
            tokens_used=max(0, self._token_meter.used - int(extra.get("tokens_before", 0) or 0)),
            uncertainties=tuple(dict.fromkeys(uncertainties)),
            analyst_notes=notes if isinstance(notes, str) else "",
            applied_changes=applied,
            ai_summary=str(getattr(investigation, "summary", "") or "") if investigation is not None else "",
            model_used=provider is not None,
        )
        # Verdict justification: one small call over the facts above (whole-binary functionality and
        # why this classification). Any failure keeps the locally built paragraph.
        if provider is not None and justification_prompt is not None and not budget.exhausted and not cancelled():
            progress("writing the verdict justification")
            try:
                justification = full_report_module.generate_justification(
                    data, provider, justification_prompt,
                    max_output_tokens=config.max_output_tokens, temperature=config.temperature,
                )
                data = dataclasses.replace(
                    data, justification=justification,
                    tokens_used=max(0, self._token_meter.used - int(extra.get("tokens_before", 0) or 0)),
                )
            except Exception as exc:  # provider error, malformed JSON: fall back, but say why
                data = dataclasses.replace(data, uncertainties=tuple(data.uncertainties) + (
                    "verdict justification written locally: " + _log_value(str(exc) or type(exc).__name__),))
        markdown = full_report_module.generate_full_report(data)
        saved = report_module.save_report(markdown, target)
        return ReportOutcome(str(saved), markdown)

    self._launch("report", work, None, None, on_success, on_error, started, extra)
    return "{0}: {1} author function(s), {2} reused from the local database…".format(
        ACTION_LABELS["report"], plan.functions_planned, len(reused)
    )

def _triage_text(self) -> Optional[str]:
    if self._latest_triage_text:
        return self._latest_triage_text
    entry = self._history.latest("triage")
    if entry is not None:
        text = entry.payload.get("text") or entry.payload.get("formatted")
        if isinstance(text, str) and text.strip():
            return text
    return None

