def __init__(self, model: str, timeout_seconds: float = 120.0) -> None:
    self._model = model
    self._timeout = timeout_seconds

def _access_token(self) -> str:
    with _lock:
        record = _load_credentials()
        if not record or not has_credentials():
            raise ChatGPTError("Sign in with ChatGPT in Settings to use your ChatGPT plan")
        if _expiry(record) > int(time.time()) + 60:
            return record["access_token"]
        try:
            refreshed = _form_post(TOKEN_URL, {
                "grant_type": "refresh_token", "client_id": record["client_id"],
                "refresh_token": record["refresh_token"], "resource": RESOURCE,
            })
        except ChatGPTError:
            # Another IDA instance may have rotated the refresh token a moment ago: use its result.
            latest = _load_credentials()
            if latest and latest.get("access_token") and latest.get("access_token") != record.get("access_token") \
                    and _expiry(latest) > int(time.time()) + 60:
                return latest["access_token"]
            raise ChatGPTError("ChatGPT session expired or was revoked; sign in again from Settings")
        if not all(isinstance(refreshed.get(k), str) and refreshed[k] for k in ("access_token", "refresh_token")):
            raise ChatGPTError("ChatGPT token refresh was incomplete; sign in again")
        record.update(access_token=refreshed["access_token"], refresh_token=refreshed["refresh_token"],
                      expires_at=_expires_at(refreshed.get("expires_in")))
        _save_credentials(record)
        return record["access_token"]

def list_models(self) -> Tuple[str, ...]:
    payload = _http_json(API_ROOT + "/models", headers={"Authorization": "Bearer " + self._access_token()})
    names = []
    models = payload.get("models")
    if isinstance(models, list):  # ChatGPT plan catalogue: slug + visibility
        names = [item["slug"] for item in models if isinstance(item, dict)
                 and item.get("visibility", "list") == "list" and isinstance(item.get("slug"), str)]
    data = payload.get("data")
    if not names and isinstance(data, list):  # public Models API shape: data[].id
        names = [item["id"] for item in data if isinstance(item, dict) and isinstance(item.get("id"), str)]
    if not names and not isinstance(models, list) and not isinstance(data, list):
        raise ChatGPTError("ChatGPT model response was invalid")
    return tuple(dict.fromkeys(names))[:100]

def generate(self, request: LLMRequest) -> LLMResponse:
    """One Responses call; transient failures before any output arrives are retried (Retry-After honoured)."""
    last_error: Optional[ChatGPTError] = None
    for attempt in range(MAX_GENERATE_ATTEMPTS):
        try:
            return self._generate_once(request)
        except _RetryableError as exc:
            last_error = ChatGPTError(str(exc))
            if attempt + 1 >= MAX_GENERATE_ATTEMPTS:
                break
            delay = exc.retry_after if exc.retry_after is not None else min(8.0, 1.0 * (2 ** attempt))
            time.sleep(min(MAX_RETRY_AFTER_SECONDS, delay) + random.uniform(0.0, 0.5))
    raise last_error or ChatGPTError("ChatGPT request failed")

def _generate_once(self, request: LLMRequest) -> LLMResponse:
    token = self._access_token()
    instructions = request.system_instruction or ""
    if request.response_mime_type == "application/json":
        # The plan endpoint has no JSON-mode switch; state the contract in the instructions.
        instructions = (instructions + "\n\n" + JSON_INSTRUCTION) if instructions else JSON_INSTRUCTION
    payload = {
        "model": self._model,
        "input": [{"role": "user", "content": request.prompt}],
        "store": False,
        "stream": True,
    }
    if instructions:
        payload["instructions"] = instructions
    body = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(API_ROOT + "/responses", data=body, method="POST", headers={
        "Authorization": "Bearer " + token, "Content-Type": "application/json",
        "Accept": "text/event-stream", "User-Agent": "IDA-AI-Malware-Analyst",
    })
    chunks = []
    received_output = False
    usage = None
    completed = False
    try:
        with urllib.request.urlopen(req, timeout=self._timeout) as response:
            total = 0
            for raw_line in response:
                total += len(raw_line)
                if total > MAX_BODY:
                    raise ChatGPTError("ChatGPT stream exceeded the size limit")
                line = raw_line.decode("utf-8", "replace").strip()
                if not line.startswith("data:"):
                    continue
                data = line[5:].strip()
                if data == "[DONE]":
                    break
                try:
                    event = json.loads(data)
                except json.JSONDecodeError:
                    continue
                if not isinstance(event, dict):
                    continue
                kind = event.get("type")
                if kind == "response.output_text.delta" and isinstance(event.get("delta"), str):
                    chunks.append(event["delta"])
                    received_output = True
                elif kind == "response.incomplete":
                    result = event.get("response")
                    details = result.get("incomplete_details") if isinstance(result, dict) else None
                    reason = details.get("reason") if isinstance(details, dict) else None
                    safe_reason = "".join(ch for ch in str(reason or "")[:64].lower() if ch.isalnum() or ch in "_-")
                    raise ChatGPTError("ChatGPT response was incomplete" + (" (" + safe_reason + ")" if safe_reason else ""))
                elif kind == "response.completed":
                    completed = True
                    result = event.get("response")
                    if isinstance(result, dict):
                        usage = usage_from(result.get("usage"), "input_tokens", "output_tokens")
                elif kind in ("response.failed", "error"):
                    result = event.get("response")
                    error = result.get("error") if isinstance(result, dict) else event.get("error")
                    safe = _safe_error_detail({"error": error} if isinstance(error, dict) else {})
                    raise ChatGPTError("ChatGPT response failed ({0})".format(safe or "request_failed"))
    except urllib.error.HTTPError as exc:
        try:
            response_body = json.loads(exc.read(65536).decode("utf-8"))
        except Exception:
            response_body = None
        detail = _safe_error_detail(response_body)
        request_id = exc.headers.get("x-request-id", "") if exc.headers else ""
        safe_request_id = "".join(ch for ch in request_id[:96] if ch.isalnum() or ch in "_-")
        suffix = (": " + detail if detail else "") + ("; request id " + safe_request_id if safe_request_id else "")
        message = "ChatGPT Responses request failed (HTTP {0}{1})".format(exc.code, suffix)
        if exc.code == 401:
            raise ChatGPTError("ChatGPT session is no longer valid; sign in again from Settings") from exc
        if exc.code == 429 or exc.code >= 500:
            if exc.code == 429 and "insufficient_quota" in detail:
                raise ChatGPTError("ChatGPT plan usage limit reached; try again later") from exc
            raise _RetryableError(message, _retry_after(exc.headers)) from exc
        raise ChatGPTError(message) from exc
    except ChatGPTError:
        raise
    except (OSError, TimeoutError) as exc:

# ---------------------------------------------------------------------------
# Name parsers
# ---------------------------------------------------------------------------


def go_package(name: str) -> str:
    """Package path of a Go symbol in IDA's dotted or underscore-mangled form; ``""`` if not Go-like."""
    if not name:
        return ""
    text = name.strip().lstrip("_") if name.startswith("__") else name.strip()
    if "/" in text or ("." in text and not text.startswith(".")):
        # Dotted form: "github.com/x/y.(*T).M", "net/http.(*Client).Do", "main.main".
        head = text
        # Strip generic instantiation brackets before splitting.
        head = re.sub(r"\[[^\]]*\]", "", head)
        slash = head.rfind("/")
        dot = head.find(".", slash + 1)
        if dot <= 0:
            return ""
        return head[:dot]
    match = _GO_UNDERSCORE_THIRD_PARTY_RE.match(text)
    if match:
        host = match.group("host").replace("_", ".")
        rest = match.group("rest")
        parts = [part for part in rest.split("_") if part]
        # github_com_owner_repo_pkg_Func -> github.com/owner/repo (best effort).
        if host.startswith(("github.com", "gitlab.com", "bitbucket.org")) and len(parts) >= 2:
            return "/".join([host] + parts[:2])
        return "/".join([host] + parts[:1]) if parts else host
    match = _GO_UNDERSCORE_STD_RE.match(text)
    if match:
        return match.group("root")
    if text.startswith("main_"):
        return "main"
    return ""


def go_module_root(package: str) -> str:
    parts = package.split("/")
    if not parts:
        return ""
    if "." not in parts[0]:
        return parts[0]
    if parts[0] in ("github.com", "gitlab.com", "bitbucket.org", "codeberg.org", "git.sr.ht") and len(parts) >= 3:
        return "/".join(parts[:3])
    if parts[0] in ("golang.org", "google.golang.org", "gopkg.in", "go.uber.org", "go.etcd.io", "k8s.io", "cloud.google.com") and len(parts) >= 2:
        return "/".join(parts[:3]) if parts[0] == "golang.org" and len(parts) >= 3 else "/".join(parts[:2])
    return "/".join(parts[:2])


def rust_crate(name: str) -> str:
    """Crate name of a mangled (legacy/v0) or demangled Rust symbol; ``""`` when not Rust-like."""
    if not name:
        return ""
    match = _RUST_LEGACY_RE.match(name)
    if match:
        length = int(match.group("len"))
        rest = match.group("rest")
        if 0 < length <= len(rest):
            crate = rest[:length]
            if re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", crate):
                return crate.lower()
        return ""
    match = _RUST_V0_RE.match(name)
    if match:
        crate = match.group("crate")
        length = int(match.group("len"))
        return crate[:length].lower() if length <= len(crate) else crate.lower()
    match = _RUST_DEMANGLED_RE.match(name)
    if match:
        return match.group("crate").lower()
    return ""


def delphi_unit(name: str) -> str:
    match = _DELPHI_AT_RE.match(name)
    if match:
        return match.group("unit")
    match = _DELPHI_SCOPED_RE.match(name)
    if match:
        return match.group("unit")
    return ""


def is_auto_named(name: str) -> bool:
    return bool(_AUTO_NAME_RE.match(name or ""))


