class ResponsiveHeader(QtWidgets.QWidget):
    """Three header groups that rearrange with the dock width (like a CSS grid with a media query).

    Wide:   [Binary] [Function ............] [Cancel Settings]
    Narrow: [Binary] [Cancel Settings]
            [Function ...........................]
    The layout imposes no minimum width, so the dock can always be narrowed.
    """

    def __init__(self, binary, function, actions, function_min_width, parent=None) -> None:
        super().__init__(parent)
        self._binary, self._function, self._actions = binary, function, actions
        self._function_min_width = function_min_width
        self._grid = QtWidgets.QGridLayout(self)
        self._grid.setContentsMargins(0, 0, 0, 0)
        self._grid.setHorizontalSpacing(6)
        self._grid.setVerticalSpacing(4)
        self._grid.setSizeConstraint(QtWidgets.QLayout.SetNoConstraint)
        self._wide: Optional[bool] = None
        self.setSizePolicy(QtWidgets.QSizePolicy.Ignored, QtWidgets.QSizePolicy.Preferred)
        self._arrange(True)

    def _wide_threshold(self) -> int:
        spacing = self._grid.horizontalSpacing() * 2
        return self._binary.sizeHint().width() + self._actions.sizeHint().width() + int(self._function_min_width()) + spacing

    def _arrange(self, wide: bool) -> None:
        if wide == self._wide:
            return
        self._wide = wide
        for widget in (self._binary, self._function, self._actions):
            self._grid.removeWidget(widget)
        top = QtCore.Qt.AlignTop
        if wide:
            self._grid.addWidget(self._binary, 0, 0, top)
            self._grid.addWidget(self._function, 0, 1)
            self._grid.addWidget(self._actions, 0, 2, top | QtCore.Qt.AlignRight)
            self._grid.setColumnStretch(0, 0)
            self._grid.setColumnStretch(1, 1)
        else:
            self._grid.addWidget(self._binary, 0, 0, top)
            self._grid.addWidget(self._actions, 0, 1, top | QtCore.Qt.AlignRight)
            self._grid.addWidget(self._function, 1, 0, 1, 2)
            self._grid.setColumnStretch(0, 1)
            self._grid.setColumnStretch(1, 0)
        self._grid.setColumnStretch(2, 0)
        self.updateGeometry()

    def resizeEvent(self, event) -> None:  # noqa: N802 - Qt override
        super().resizeEvent(event)
        self._arrange(event.size().width() >= self._wide_threshold())

