# Status words that colour the status pill (checked in order; first match wins).
_STATUS_ERROR_WORDS = ("failed", "error", "invalid", "refused", "expired", "unavailable", "not ", "no api key", "cancel")
_STATUS_OK_WORDS = ("complete", "finished", "saved", "copied", "queued", "received", "shown instantly", "ready", "applied")

def status_state(text: str, busy: bool = False) -> str:
    """Colour state of the status pill: busy / error / ok / info."""
    if busy:
        return "busy"
    lowered = (text or "").lower()
    if any(word in lowered for word in _STATUS_ERROR_WORDS):
        return "error"
    if any(word in lowered for word in _STATUS_OK_WORDS):
        return "ok"
    return "info"

