    """Colour the status pill (busy / ok / error / info); purely visual."""
    label = self._status_label
    if label is None:
        return
    if busy is None:
        busy = self._progress is not None and not self._progress.isHidden()
    text = label.text()
    state = status_state(text[len("Status: "):] if text.startswith("Status: ") else text, busy)
    if label.property("state") != state:
        label.setProperty("state", state)
        try:  # re-apply the stylesheet so the [state=...] rule takes effect
            label.style().unpolish(label)
            label.style().polish(label)
        except Exception:
            pass

