        sign_out=self.sign_out_chatgpt,
        forget_account=self.forget_chatgpt_account,
        cancel_sign_in=self.cancel_sign_in,
    )

def external_ai_notice(self) -> Optional[str]:
    if not self._config.show_external_ai_notice:
        return None
    return "External AI: {0} ({1})".format(self._config.provider_label, self._config.active_model)

# -- settings (Settings dialog) -------------------------------------------

def config_path(self) -> Path:

    path = self.config_path()
    try:
        file_config = load_file_config(path)
    except ConfigurationError:
        # An unreadable or invalid file is replaced rather than left blocking the save.
        file_config = PluginConfig()
    file_updates = {name: value for name, value in settings.items() if name in _CONFIG_KEYS}
    try:
        file_candidate = file_config.with_updates(**file_updates)
    except ConfigurationError as exc:
        return "Invalid settings: {0}".format(exc)
    try:
        # Rewriting the file also drops API-key fields an older version may have stored.
        save_config(file_candidate, path)
    except OSError as exc:
        # The file is a convenience; the settings still take effect for this IDA session.
        self._config = runtime
        self._notice_changed()
        log_event(self._logger, "settings_save_failed", error=type(exc).__name__, path=str(path))
        return "Applied for this session, but could not write {0} ({1}). Check folder permissions.".format(
            path, type(exc).__name__
        )
    self._config = runtime
    log_event(
        self._logger,
        "settings_saved",
        provider=runtime.provider,
        model=_log_value(runtime.active_model),
        signed_in=runtime.is_signed_in(),
    )
    self._apply_token_policy()
    self._notice_changed()
    return SETTINGS_SAVED_STATUS

def _apply_token_policy(self) -> None:
    """Session-only ChatGPT tokens unless the analyst chose "Stay signed in"."""
    try:
        from ida_ai_malware_analyst_plugin.llm.chatgpt import set_token_persistence

        set_token_persistence(self._config.remember_chatgpt_sign_in)
    except Exception as exc:  # storage policy must never stop the plugin
        log_event(self._logger, "token_policy_failed", error=_log_value(type(exc).__name__))

def _notice_changed(self) -> None:
    if self._panel is not None:
        try:
            self._panel.set_notice(self.external_ai_notice())
        except Exception:
            pass

def _panel_closed(self) -> None:
    self._panel = None

def shutdown(self) -> None:
    self._change_tracker.uninstall()

    kind, self._running_kind = self._running_kind, None
    if task is not None:
        task.cancel()
        log_event(self._logger, "action_cancelled", kind=kind)
    settings_task, self._settings_task = self._settings_task, None
    self._settings_request = None
    if settings_task is not None:
        settings_task.cancel()

def _default_provider(self) -> LLMProvider:
    return build_provider(self._config)

def _has_ai_access(self) -> bool:
    """Signed in with ChatGPT, or an API key is available for the selected key-based provider."""
    return self._config.is_signed_in()

def sign_in_chatgpt(
    self, on_result: Callable[[str], None], on_error: Callable[[str], None], on_url: Optional[Callable[[str], None]] = None
) -> str:
    """Run the browser OAuth flow on a worker, then activate ChatGPT.

    ``on_url`` (UI thread) receives the sign-in link as soon as it exists, so the
    dialog can offer it for copying when no browser opens.
    """
    from ida_ai_malware_analyst_plugin.llm.chatgpt import sign_in

    def apply(message: str) -> None:
        self._forget_available_models("chatgpt")
        status = self.save_settings({"provider": "chatgpt"})
        on_result(message + " — " + status)

    return self._start_settings_request(
        "chatgpt_sign_in", lambda: sign_in(on_url=self._ui_callback(on_url)), apply, on_error,
        "Opening ChatGPT sign-in in your browser…",
    )

def cancel_sign_in(self) -> str:
    """Abort a ChatGPT browser sign-in that is waiting for the browser."""
    from ida_ai_malware_analyst_plugin.llm import chatgpt

    cancelled = chatgpt.cancel_sign_in()
    return "Cancelling sign-in…" if cancelled else "No sign-in is in progress"

def _ui_callback(self, callback: Optional[Callable[[str], None]]) -> Optional[Callable[[str], None]]:
    """Wrap a UI callback so a worker thread can call it safely (delivered on IDA's thread)."""
    if callback is None:
        return None

    def deliver(value: str) -> None:
        self._deliver_on_ida_thread(lambda: callback(value))

    return deliver

def sign_out_chatgpt(self, on_result: Callable[[str], None], on_error: Callable[[str], None]) -> str:
    from ida_ai_malware_analyst_plugin.llm.chatgpt import sign_out
    def done(message: str) -> None:
        self._forget_available_models("chatgpt")
        self._notice_changed()
        on_result(message)
    return self._start_settings_request(
        "chatgpt_sign_out", sign_out, done, on_error, "Disconnecting ChatGPT…"
    )

def forget_chatgpt_account(self, on_result: Callable[[str], None], on_error: Callable[[str], None]) -> str:
    from ida_ai_malware_analyst_plugin.llm.chatgpt import forget_account
    def done(message: str) -> None:
        self._forget_available_models("chatgpt")
        self._notice_changed()
        on_result(message)
    return self._start_settings_request(
        "chatgpt_forget_account", forget_account, done, on_error, "Forgetting ChatGPT account…"
    )

def _prompt(self, name: str) -> str:
    return load_function_prompt(self._plugin_root / "prompts" / name)

