def _settings_saved(self, status: str) -> None:
    self._set_status(status)
    if self._sweep_button is not None:  # sweep size may have changed
        self._sweep_button.setText(self._sweep_caption())

def _settings_closed(self) -> None:
    self._settings_dialog = None

def _update_cancel_button(self) -> None:
    """Reflect the controller's busy state: Cancel, action buttons, progress and elapsed time."""
    try:
        running = bool(self._actions.is_running())
    except Exception:
        running = False
    if self._cancel_button is not None:
        self._cancel_button.setEnabled(running)
    for button in list(self._action_buttons) + [self._sweep_button, self._binary_names_button, self._ask_send]:
        if button is not None:
            try:
                button.setEnabled(not running)
            except Exception:
                pass
    if self._progress is not None:
        self._progress.setVisible(running)
    self._restyle_status(running)
    if running:
        if self._busy_started is None:
            self._busy_started = time.monotonic()
        if self._busy_timer is not None and not self._busy_timer.isActive():
            self._busy_timer.start()
        self._tick_busy()
    else:
        self._busy_started = None
        if self._busy_timer is not None:
            self._busy_timer.stop()
        if self._elapsed_label is not None:
            self._elapsed_label.setText("")

