def _repolish(widget: Any, name: str, value: Any) -> None:
    """Set a style property and re-apply the stylesheet so ``[name="value"]`` rules take effect."""
    if widget is None or widget.property(name) == value:
        return
    widget.setProperty(name, value)
    try:
        widget.style().unpolish(widget)
        widget.style().polish(widget)
    except Exception:
        pass

