def _paths() -> Tuple[Path, Path]:
    root = user_config_dir() / "ida_ai_malware_analyst"
    return root / "chatgpt_credentials.dat", root / "chatgpt_host_id"


def _protect(raw: bytes) -> bytes:
    if os.name == "nt":
        class Blob(ctypes.Structure):
            _fields_ = [("cbData", ctypes.c_ulong), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]
        source_buf = ctypes.create_string_buffer(raw)
        source = Blob(len(raw), ctypes.cast(source_buf, ctypes.POINTER(ctypes.c_ubyte)))
        result = Blob()
        crypt = ctypes.windll.crypt32.CryptProtectData
        crypt.argtypes = [ctypes.POINTER(Blob), ctypes.c_wchar_p, ctypes.c_void_p,
                          ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(Blob)]
        crypt.restype = ctypes.c_bool
        if not crypt(ctypes.byref(source), "IDA AI Malware Analyst ChatGPT session", None, None, None, 1, ctypes.byref(result)):
            raise ChatGPTError("Windows credential protection failed")
        try:
            return ctypes.string_at(result.pbData, result.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(result.pbData)
    return raw


def _unprotect(raw: bytes) -> bytes:
    if os.name == "nt":
        class Blob(ctypes.Structure):
            _fields_ = [("cbData", ctypes.c_ulong), ("pbData", ctypes.POINTER(ctypes.c_ubyte))]
        source_buf = ctypes.create_string_buffer(raw)
        source = Blob(len(raw), ctypes.cast(source_buf, ctypes.POINTER(ctypes.c_ubyte)))
        result = Blob()
        crypt = ctypes.windll.crypt32.CryptUnprotectData
        crypt.argtypes = [ctypes.POINTER(Blob), ctypes.POINTER(ctypes.c_wchar_p), ctypes.c_void_p,
                          ctypes.c_void_p, ctypes.c_void_p, ctypes.c_ulong, ctypes.POINTER(Blob)]
        crypt.restype = ctypes.c_bool
        if not crypt(ctypes.byref(source), None, None, None, None, 1, ctypes.byref(result)):
            raise ChatGPTError("Saved ChatGPT credentials could not be decrypted; sign in again")
        try:
            return ctypes.string_at(result.pbData, result.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(result.pbData)
    return raw


def _write_private(path: Path, raw: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    fd = os.open(str(temporary), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, stat.S_IRUSR | stat.S_IWUSR)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(raw)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.chmod(str(temporary), stat.S_IRUSR | stat.S_IWUSR)
        except OSError:
            pass
        os.replace(str(temporary), str(path))
    except BaseException:
        try:
            temporary.unlink()
        except OSError:
            pass
        raise


# --- Token storage policy ------------------------------------------------------
# Default: session-only. Access/refresh/id tokens live in this process's memory and are
# discarded (and the refresh token revoked) when IDA closes; only the non-secret
# registration (client id, account subject, e-mail) is written to disk so the next
# sign-in is quick. "Stay signed in" keeps the tokens on disk, DPAPI-encrypted.
TOKEN_FIELDS = ("access_token", "refresh_token", "id_token", "expires_at", "scopes")
_persist_tokens = False
_memory_tokens: Optional[dict] = None


def set_token_persistence(persist: bool) -> None:
    """Switch between session-only tokens (default) and encrypted on-disk tokens; migrates what exists."""
    global _persist_tokens, _memory_tokens
    with _lock:
        persist = bool(persist)
        if persist and _persist_tokens:
            return
        try:
            if not persist:
                # Tokens a previous "Stay signed in" (or older version) left on disk move into
                # memory for this session - they are revoked when it ends - and leave the disk.
                disk = _read_disk_record()
                if disk is not None and any(key in disk for key in TOKEN_FIELDS) and not _memory_tokens:
                    _memory_tokens = dict({key: disk[key] for key in TOKEN_FIELDS if key in disk}, subject=disk.get("subject"))
            record = _load_credentials()
        except ChatGPTError:
            record = None
        _persist_tokens = persist
        if record is not None:
            _save_credentials(record)  # writes tokens to disk, or keeps them in memory and scrubs the disk
        if persist:
            _memory_tokens = None


def tokens_persisted() -> bool:
    return _persist_tokens


def end_session(revoke: bool = True) -> None:
    """Called when IDA closes the database: forget session-only tokens (revoking the refresh token first)."""
    global _memory_tokens
    if _persist_tokens:
        return
    with _lock:
        tokens, _memory_tokens = _memory_tokens, None
    if revoke and tokens and tokens.get("refresh_token"):
        try:
            record = _read_disk_record() or {}
            _revoke_refresh_token(tokens["refresh_token"], record.get("client_id", ""), attempts=1, timeout=3.0)
        except Exception:
            pass


def _read_disk_record() -> Optional[dict]:
    path, _ = _paths()
    try:
        value = json.loads(_unprotect(path.read_bytes()).decode("utf-8"))
    except FileNotFoundError:
        return None
    except (OSError, ValueError, UnicodeDecodeError) as exc:
        raise ChatGPTError("Saved ChatGPT credentials are unavailable; sign in again") from exc
    if not isinstance(value, dict) or not all(isinstance(value.get(k), str) and value.get(k) for k in
            ("client_id", "subject")):
        raise ChatGPTError("Saved ChatGPT credentials are incomplete; sign in again")
    return value


def _load_credentials() -> Optional[dict]:
    record = _read_disk_record()
    if record is None:
        return None
    if not _persist_tokens:
        # Never use tokens that may still sit on disk from "Stay signed in"; only this session's.
        record = {key: value for key, value in record.items() if key not in TOKEN_FIELDS}
        if _memory_tokens and _memory_tokens.get("subject") == record.get("subject"):
            record.update({key: value for key, value in _memory_tokens.items() if key in TOKEN_FIELDS})
    return record


def has_credentials() -> bool:
    try:
        record = _load_credentials()
        return bool(record and all(isinstance(record.get(k), str) and record.get(k)
                                   for k in ("access_token", "refresh_token", "id_token")))
    except ChatGPTError:
        return False


def signed_in_email() -> Optional[str]:
    """E-mail of the signed-in ChatGPT account (non-secret registration detail), when known."""
    try:
        record = _load_credentials()
    except ChatGPTError:
        return None
    email = record.get("email") if record else None
    return email if isinstance(email, str) and email else None


def has_saved_account() -> bool:
    """Whether account registration details remain, including after disconnect."""
    try:
        return _load_credentials() is not None
    except ChatGPTError:
        return False


def _save_credentials(value: dict) -> None:
    """Persist the record; in session-only mode the tokens go to memory and only registration to disk."""
    global _memory_tokens
    path, _ = _paths()
    if _persist_tokens:
        stored = value
    else:
        tokens = {key: val for key, val in value.items() if key in TOKEN_FIELDS}
        _memory_tokens = dict(tokens, subject=value.get("subject")) if tokens else None
        stored = {key: val for key, val in value.items() if key not in TOKEN_FIELDS}
    encoded = json.dumps(stored, separators=(",", ":")).encode("utf-8")
    _write_private(path, _protect(encoded))


def _b64url(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")


def _decode_part(part: str) -> bytes:
    return base64.urlsafe_b64decode(part + "=" * (-len(part) % 4))

